            padding: 60px 0;
            background: var(--white);
        }
        .section-title {
            text-align: center;
            font-size: 32px;
            margin-bottom: 40px;
        }
        .category-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }
        .category-card {
            background: var(--bg-light);
            padding: 30px;
            border-radius: 10px;
            text-align: center;
            transition: transform 0.3s;
        }
        .category-card:hover {
            transform: translateY(-5px);
        }
        .category-icon {
            font-size: 40px;
            margin-bottom: 15px;
            color: var(--primary-color);
        }

        /* Featured Courses */
