        .course-card {
            background: var(--white);
            border-radius: 10px;
            overflow: hidden;
            box-shadow: 0 4px 6px rgba(0,0,0,0.05);
            transition: box-shadow 0.3s;
        }
        .course-card:hover {
            box-shadow: 0 10px 15px rgba(0,0,0,0.1);
        }
        .course-thumb {
            height: 180px;
            background-color: #cbd5e1;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #64748b;
            font-weight: 500;
        }
        .course-info {
            padding: 20px;
        }
        .course-tag {
            font-size: 12px;
            color: var(--primary-color);
            background: #eff6ff;
            padding: 4px 8px;
            border-radius: 4px;
            display: inline-block;
            margin-bottom: 10px;
        }
        .course-title {
            font-size: 18px;
            margin-bottom: 10px;
        }
        .course-meta {
            display: flex;
            justify-content: space-between;
            color: var(--text-light);
            font-size: 14px;
            margin-bottom: 15px;
        }
        .course-price {
            font-size: 20px;
            color: var(--primary-color);
            font-weight: 700;
        }

        /* Footer */
        footer {
            background: #1f2937;
            color: #d1d5db;
            padding: 50px 0 20px;
        }
        .footer-content {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 40px;
            margin-bottom: 40px;
        }
        .footer-col h3 {
            color: var(--white);
            margin-bottom: 20px;
        }
        .footer-col ul {
            list-style: none;
        }
        .footer-col ul li {
            margin-bottom: 10px;
        }
        .footer-col a {
            color: #d1d5db;
            text-decoration: none;
        }
        .footer-col a:hover {
            color: var(--white);
        }
        .copyright {
            text-align: center;
            border-top: 1px solid #374151;
            padding-top: 20px;
            font-size: 14px;
        }

        @media (max-width: 768px) {
            .hero h1 { font-size: 32px; }
            .nav-links { display: none; } 
            .mobile-menu-btn { display: block; }
        }
    </style>
</head>
